{
  "spells": [
    {
      "id": "spell_faith_13",
      "theory": "群祷庇护将信众的魔力汇聚成一层薄壳状护罩，护罩没有固定形态，依靠参与者持续供给而存在。护罩的强度取决于同时维持的人数，而非单个人的力量，因此参与者一旦疲劳退出，护罩就会变薄。它只能抵挡飞溅的碎石、风沙和轻微冲击，无法阻挡刀剑或重物。护罩的边界模糊，从内部看像一层微光雾气，从外部看只是空气微微扭曲。",
      "casting": "参与者围成松散圆环，双手交叠于胸前，齐声念诵同一短句，并在句尾同时向中心送出魔力。领诵者用指尖在空中画一个不闭合的弧线，作为护罩的起始锚点。",
      "failure": "若有人节奏错乱或提前收手，护罩会从那一侧裂开，微光雾气随之消散。参与者会感到一阵眩晕和手指发麻，短时间内无法再次汇聚魔力，护罩彻底消失。",
      "counters": [
        "用长杆从护罩薄弱处缓慢刺入，可引导护罩沿杆身裂开。",
        "向参与者投掷沙土使其分心，打乱念诵节奏即可削弱护罩。"
      ],
      "socialConsequences": "乡约见证下的民事承诺常借助群祷庇护来增强信用，因为参与者众目睽睽，难以作假。河谷的农户愿意为保护庄稼而共同施术，但若有人借护罩掩护偷运货物，乡约便会追究。城镇公会要求施术前登记参与者名单，以防有人混入图谋不轨。港口船主担心护罩延误装卸，但若用于保护货物免受风浪，港务则允许在指定区域施放。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时护罩边缘抖动明显，偶尔出现短暂缺口。",
        "熟练者能让护罩表面更均匀，减少局部薄弱点。",
        "高熟练度可让护罩在参与者疲劳时缓慢收缩，而非突然破裂。",
        "更高熟练度使护罩维持稳定，但仍无法抵挡刀剑劈砍。"
      ]
    },
    {
      "id": "spell_faith_14",
      "theory": "祓界仪轨以魔力冲刷有限区域内的低阶邪秽，将其驱散或压制。邪秽并非实体，而是残留的负面魔力痕迹，因此仪轨只能清理没有自主意识的存在。区域内若有神性存在，仪轨无法将其驱逐，只能暂时削弱其影响。清理效果取决于施术者注入的魔力量，但无法改变区域本身的物理性质，也不能治愈被邪秽伤害的人。",
      "casting": "施术者以树脂粉末在地面画出闭合的圆环，站在环心，双手向外推开，同时将魔力沿圆环均匀送出。圆环闭合后，施术者需保持站立，直到圆环内的微光消退。",
      "failure": "若圆环未闭合或魔力输送中断，邪秽会从缺口处反涌，使圆环内的微光变成暗红色。施术者会感到一阵寒意，树脂粉末燃烧成灰，区域内的邪秽只是暂时退开，并未被清除。",
      "counters": [
        "在圆环闭合前踢散树脂粉末，可让仪轨无法启动。",
        "向圆环内投掷带有新鲜血迹的物品，可干扰魔力流动使仪轨失效。"
      ],
      "socialConsequences": "河谷的乡约允许在公共场地施放祓界仪轨，但若清理的是他人宅院，须先征得主人同意。城镇公会要求施术前报备，以防有人借清理之名掩盖纵火或盗窃。港口船主常请人清理船舱，但港务规定若清理导致货物损坏，须由施术者赔偿。若有人用祓界仪轨驱赶他人，将被视为侵犯隐私，乡约和公会都会介入。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时圆环内的微光忽明忽暗，清理范围略小于预期。",
        "熟练者能让微光均匀覆盖圆环，邪秽退散更彻底。",
        "高熟练度可让仪轨在树脂燃尽前保持稳定，减少魔力浪费。",
        "更高熟练度使圆环边界清晰，但仍无法驱逐神性存在。"
      ]
    }
  ]
}
